!function(r){function p(p){for(var e,i,o=p[0],c=p[1],m=p[2],u=0,j=[];u<o.length;u++)i=o[u],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&j.push(n[i][0]),n[i]=0;for(e in c)Object.prototype.hasOwnProperty.call(c,e)&&(r[e]=c[e]);for(s&&s(p);j.length;)j.shift()();return a.push.apply(a,m||[]),t()}function t(){for(var r,p=0;p<a.length;p++){for(var t,i=a[p],o=!0,c=1;c<i.length;c++)t=i[c],0!==n[t]&&(o=!1);o&&(a.splice(p--,1),r=e(e.s=i[0]))}return r}function e(p){if(i[p])return i[p].exports;var t=i[p]={i:p,l:!1,exports:{}};return r[p].call(t.exports,t,t.exports,e),t.l=!0,t.exports}var i={},n={11:0},a=[];e.m=r,e.c=i,e.d=function(r,p,t){e.o(r,p)||Object.defineProperty(r,p,{enumerable:!0,get:t})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,p){if(1&p&&(r=e(r)),8&p)return r;if(4&p&&"object"==typeof r&&r&&r.__esModule)return r;var t=Object.create(null);if(e.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:r}),2&p&&"string"!=typeof r)for(var i in r)e.d(t,i,function(p){return r[p]}.bind(null,i));return t},e.n=function(r){var p=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(p,"a",p),p},e.o=function(r,p){return Object.prototype.hasOwnProperty.call(r,p)},e.p="";var o=window.webpackJsonp=window.webpackJsonp||[],c=o.push.bind(o);o.push=p,o=o.slice();for(var m=0;m<o.length;m++)p(o[m]);var s=c;a.push([47,0]),t()}({47:function(r,p,t){"use strict";t.r(p);var e=t(0);Object(e.a)("jp","army",t(48),t(1))},48:function(r){r.exports=JSON.parse('{"category":[{"name":"日本","link":"jp_shortcut"},{"name":"陆战武器","link":"jp_army"},{"name":"轻武器","link":"jp_army#jp_army_iw"}],"model":"89式掷弹筒","description":"<h6>综述：</h6><p>二战前后，日本陆军装备了大量89式50毫米掷弹筒，其中每个步兵小队配备1个掷弹筒分队（排、班一级），每个掷弹筒分队配备3支掷弹筒，3人编为一组（可以携带药弹54发）。</p><p>89式50毫米掷弹筒其实是一种可由单兵操作的小口径迫击炮，携带便利，能不受地形影响、随时随地对战场进行火力支援，利用其射角大、弹道弯曲、射程远的特点，日军步兵用它来大量杀伤躲藏在工事或者隐蔽物后面的敌人，以及摧毁轻、重机枪火力点，在中国战场、早期的东南亚战场及太平洋战争初期，日军的89式50毫米掷弹筒发挥了极大作用，是二战日本陆军部队最著名的三件标准配备之一（其它两件分别是：三八大盖和92式步兵炮），美军对此型掷弹筒的评价是：“日本陆军唯一值得评价的武器”。在二战前后，日本共生产了十多万具89式掷弹筒。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/jp/army/jp_army_iw89GL_11.jpg","description":"<h6>89式50毫米掷弹筒</h6><p></p><p>基本技术数据：</p><p>口径：50毫米；</p><p>武器全长：608毫米（炮管长540毫米）；</p><p>武器全重：4.7公斤；</p><p>炮弹种类：专用榴弹（0.79公斤）、普通手榴弹，化学弹药等；</p><p>最大射程：670米（使用有翼榴弹时可以达到800米）。</p>","caption":""}],"part2title":"战场上的89式掷弹筒","part2description":"","part2content":[{"image":"imgs/jp/army/jp_army_iw89GL_21.jpg","description":"1942年5月，中国抗日战场，淅赣战役期间，在淅江金华地区作战的日军第14军步兵师团步兵正使用89式50毫米掷弹筒攻击中国抗日军队的阵地。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_22.jpg","description":"中国抗日战场，两名埋伏在草丛中的日军步兵正使用89式50毫米掷弹筒攻击中国军队。由于89式50毫米掷弹筒威力较大，榴弹爆炸的威力相当于普通手雷的2-3倍，因此在战场上对抗日军队威胁极大。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_23.jpg","description":"中国抗日战场，正在向中国军队阵地进攻的一个日军步兵小组，小组中有一名日军手持着89式50毫米掷弹筒，主要是用来对付机枪火力点。注：89式掷弹筒体积小、重量轻，单兵携行方便，性能可靠且实用，全炮加上一个可装8枚榴弹的弹药袋，整套装备下来也不超过7公斤，甚至比一挺捷克式轻机枪还要轻便。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_24.jpg","description":"二战战场，一个日军步兵小队准备发起进攻，其中一名日军正在使用89式50毫米掷弹筒进行射击。89式掷弹筒除了发射自身配备的炮弹外，还能发射手榴弹，使用时不受地形限制，在近战中占有火力上的优势。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_25.jpg","description":"一名采用卧姿发射的日军士兵正在使用89式50毫米掷弹筒作射击准备。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_26.jpg","description":"绘画：二战中，已落地的日军伞兵正在使用89式50毫米掷弹筒作射击准备，地上放着一具用于伞降时的掷弹筒包装外壳。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_27.jpg","description":"1937年，中国抗日战场,上海会战期间，日军步兵在上海沿岸实施登陆作战，一名已登岸的日军士兵使用89式50毫米掷弹筒向中国守军发射炮弹。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_28.jpg","description":"一队正在使用89式50毫米掷弹筒进行射击训练的日军。注：89式掷弹筒虽然有膛线，却没有瞄准具，能够打准完全凭借训练有素和操作经验。在二战中前期，经过训练的日军士兵大多能够熟练操纵掷弹筒，其首发命中率高达85-95%，因此杀伤力相当强。而后随着战争发展，具有一定战斗素养的日军老兵在战争中大量伤亡后，新入伍的日军士兵对于掷弹筒的操纵水平大大下降，到了太平洋战争后期，日军89式50毫米掷弹筒已无法对反攻的美军造成太大威胁。","caption":""},{"image":"imgs/jp/army/jp_army_iw89GL_29.jpg","description":"二战太平洋战场，正在接受日军投降的美军官兵清点收缴日军武器，其中一张桌面上摆有多具日军89式50毫米掷弹筒。","caption":""}]}')}});